# Get ALL defined symbols sorted by address
nm -D --defined-only -n libmonosgen-2.0.so | awk '
  { addrs[NR] = strtonum("0x" $1); names[NR] = $3; count = NR }
  END {
    targets[1] = 0x222098; tnames[1] = "#01"
